let _markdown = "\n\n<Installation name=\"accordion\" />\n\nUsage [#usage]\n\n<FeedbackBlock\n  id=\"3ce6ab7608663b40\"\n  body=\"Based on\nRadix UI Accordion, useful for FAQ sections.\"\n>\n  Based on\n  [Radix UI Accordion](https://www.radix-ui.com/primitives/docs/components/accordion), useful for FAQ sections.\n</FeedbackBlock>\n\n> <FeedbackBlock id=\"7625b5b5e26893b4\" body=\"For @fumadocs/base-ui, this is based on Base UI instead.\">\n>   For `@fumadocs/base-ui`, this is based on [Base UI](https://base-ui.com/react/components/accordion) instead.\n> </FeedbackBlock>\n\n<FeedbackBlock id=\"3465a179a67fbf4a\" body=\"Use it in MDX files or as a normal React component.\">\n  Use it in MDX files or as a normal React component.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"MDX\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"MDX\">\n      MDX\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"React.js\">\n      React.js\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"MDX\">\n    ```mdx\n    ---\n    title: Hello World\n    ---\n\n    import { Accordion, Accordions } from 'fumadocs-ui/components/accordion';\n\n    <Accordions type=\"single\">\n      <Accordion title=\"My Title\">My Content</Accordion>\n    </Accordions>\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"React.js\">\n    ```tsx\n    import { Accordion, Accordions } from 'fumadocs-ui/components/accordion';\n\n    export default function Page() {\n      return (\n        <Accordions type=\"single\">\n          <Accordion title=\"My Title\">My Content</Accordion>\n        </Accordions>\n      );\n    }\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nAccordions [#accordions]\n\n<TypeTable\n  type={{\n  \"name\": \"AccordionsProps\",\n  \"description\": \"\",\n  \"entries\": [\n    {\n      \"name\": \"asChild\",\n      \"description\": \"\",\n      \"tags\": [],\n      \"type\": \"boolean | undefined\",\n      \"simplifiedType\": \"boolean\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"type\",\n      \"description\": \"\",\n      \"tags\": [],\n      \"type\": \"\\\"single\\\" | \\\"multiple\\\"\",\n      \"simplifiedType\": \"\\\"multiple\\\" | \\\"single\\\"\",\n      \"required\": true,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"disabled\",\n      \"description\": \"Whether or not an accordion is disabled from user interaction.\",\n      \"tags\": [\n        {\n          \"name\": \"defaultValue\",\n          \"text\": \"false\"\n        }\n      ],\n      \"type\": \"boolean | undefined\",\n      \"simplifiedType\": \"boolean\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"orientation\",\n      \"description\": \"The layout in which the Accordion operates.\",\n      \"tags\": [\n        {\n          \"name\": \"default\",\n          \"text\": \"vertical\"\n        }\n      ],\n      \"type\": \"\\\"horizontal\\\" | \\\"vertical\\\" | undefined\",\n      \"simplifiedType\": \"\\\"vertical\\\" | \\\"horizontal\\\"\",\n      \"required\": false,\n      \"deprecated\": false\n    }\n  ]\n}}\n/>\n\nAccordion [#accordion]\n\n<TypeTable\n  type={{\n  \"name\": \"AccordionProps\",\n  \"description\": \"\",\n  \"entries\": [\n    {\n      \"name\": \"asChild\",\n      \"description\": \"\",\n      \"tags\": [],\n      \"type\": \"boolean | undefined\",\n      \"simplifiedType\": \"boolean\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"disabled\",\n      \"description\": \"Whether or not an accordion item is disabled from user interaction.\",\n      \"tags\": [\n        {\n          \"name\": \"defaultValue\",\n          \"text\": \"false\"\n        }\n      ],\n      \"type\": \"boolean | undefined\",\n      \"simplifiedType\": \"boolean\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"value\",\n      \"description\": \"\",\n      \"tags\": [],\n      \"type\": \"string | undefined\",\n      \"simplifiedType\": \"string\",\n      \"required\": false,\n      \"deprecated\": false\n    }\n  ]\n}}\n/>\n\nLinking to Accordion [#linking-to-accordion]\n\n<FeedbackBlock id=\"5cf00688f767d137\" body=\"You can specify an id for accordion. The accordion will automatically open when the user is navigating to the page with the specified id in hash parameter.\">\n  You can specify an `id` for accordion. The accordion will automatically open when the user is navigating to the page with the specified `id` in hash parameter.\n</FeedbackBlock>\n\n```mdx\n<Accordions>\n<Accordion title=\"My Title\" id=\"my-title\">\n\nMy Content\n\n</Accordion>\n</Accordions>\n```\n\n> <FeedbackBlock id=\"aabcb65910c4c8da\" body=\"The value of accordion is same as title by default. When an id presents, it will be used as the value instead.\">\n>   The value of accordion is same as title by default. When an id presents, it will be used as the value instead.\n> </FeedbackBlock>\n";
